using System;
using System.Collections.Generic;
using System.Data.SQLite;
using System.Windows;
using System.Windows.Media;

namespace Mazandasht.Desktop.Services
{
    /// <summary>
    /// Theme names shipped with the application. Each name maps to
    /// Assets/Themes/Theme.&lt;Name&gt;.xaml, generated by tools/build_themes.py.
    /// </summary>
    public enum AppTheme
    {
        Windows = 0,
        Dark = 1,
        Caspian = 2,
        Forest = 3
    }

    /// <summary>
    /// Applies and persists the application theme.
    ///
    /// The shared styles in Assets/Themes/Common.xaml use DynamicResource, so
    /// replacing the merged theme dictionary re-skins every themed control at
    /// runtime without recompiling.
    /// </summary>
    public static class ThemeService
    {
        public const string SettingKey = "ui.theme";
        public const string Category = "UI";

        private static readonly Dictionary<AppTheme, string> ThemeFiles =
            new Dictionary<AppTheme, string>
            {
                { AppTheme.Windows, "Assets/Themes/Theme.Windows.xaml" },
                { AppTheme.Dark,    "Assets/Themes/Theme.Dark.xaml" },
                { AppTheme.Caspian, "Assets/Themes/Theme.Caspian.xaml" },
                { AppTheme.Forest,  "Assets/Themes/Theme.Forest.xaml" }
            };

        public static AppTheme Current { get; private set; } = AppTheme.Windows;

        public static IEnumerable<AppTheme> Supported
        {
            get { return ThemeFiles.Keys; }
        }

        public static string DisplayName(AppTheme theme)
        {
            switch (theme)
            {
                case AppTheme.Windows: return "ویندوز (پیش‌فرض)";
                case AppTheme.Dark:    return "تیره";
                case AppTheme.Caspian: return "کاسپین";
                case AppTheme.Forest:  return "جنگل";
                default:               return theme.ToString();
            }
        }

        /// <summary>
        /// Applies the saved theme at start-up, before the main window is shown.
        /// </summary>
        public static void ApplySavedTheme(string databasePath)
        {
            var saved = ReadSavedTheme(databasePath);
            Apply(saved);
        }

        public static void Apply(AppTheme theme)
        {
            var root = new ResourceDictionary();

            var common = new ResourceDictionary
            {
                Source = new Uri("Assets/Themes/Common.xaml", UriKind.Relative)
            };
            root.MergedDictionaries.Add(common);

            var themeDictionary = new ResourceDictionary
            {
                Source = new Uri(ThemeFiles[theme], UriKind.Relative)
            };
            root.MergedDictionaries.Add(themeDictionary);

            Application.Current.Resources = root;
            Current = theme;
        }

        public static void SaveTheme(string databasePath, AppTheme theme, string userId)
        {
            Apply(theme);
            using (var connection = new SQLiteConnection(
                "Data Source=" + databasePath + ";Version=3;Pooling=True;"))
            {
                connection.Open();
                using (var transaction = connection.BeginTransaction())
                {
                    const string sql = @"INSERT INTO app_settings(setting_key,value_json,category,updated_by)
                        VALUES(@key,@value,@category,@user)
                        ON CONFLICT(setting_key) DO UPDATE SET
                            value_json=@value, category=@category, updated_by=@user,
                            updated_at_utc=strftime('%Y-%m-%dT%H:%M:%fZ','now');";
                    using (var command = new SQLiteCommand(sql, connection, transaction))
                    {
                        command.Parameters.AddWithValue("@key", SettingKey);
                        command.Parameters.AddWithValue("@value", theme.ToString());
                        command.Parameters.AddWithValue("@category", Category);
                        command.Parameters.AddWithValue("@user", (object)userId ?? DBNull.Value);
                        command.ExecuteNonQuery();
                    }
                    transaction.Commit();
                }
            }
        }

        private static AppTheme ReadSavedTheme(string databasePath)
        {
            try
            {
                using (var connection = new SQLiteConnection(
                    "Data Source=" + databasePath + ";Version=3;Pooling=True;"))
                {
                    connection.Open();
                    using (var command = new SQLiteCommand(
                        "SELECT value_json FROM app_settings WHERE setting_key=@key;", connection))
                    {
                        command.Parameters.AddWithValue("@key", SettingKey);
                        var value = Convert.ToString(command.ExecuteScalar());
                        AppTheme parsed;
                        if (!String.IsNullOrWhiteSpace(value) &&
                            Enum.TryParse<AppTheme>(value, out parsed) &&
                            Enum.IsDefined(typeof(AppTheme), parsed))
                        {
                            return parsed;
                        }
                    }
                }
            }
            catch
            {
                // A missing or unreadable setting falls back to the default theme.
            }
            return AppTheme.Windows;
        }

        /// <summary>
        /// Theme-aware brush lookup for code-built windows.
        /// </summary>
        public static SolidColorBrush Brush(string resourceKey)
        {
            var resource = Application.Current.Resources[resourceKey];
            var brush = resource as SolidColorBrush;
            if (brush != null) return brush;
            var color = (Color?)resource;
            if (color.HasValue) return new SolidColorBrush(color.Value);
            return Application.Current.Resources[resourceKey] as SolidColorBrush;
        }

        public static Color Color(string resourceKey)
        {
            var color = (Color?)Application.Current.Resources[resourceKey];
            if (color.HasValue) return color.Value;
            var brush = Application.Current.Resources[resourceKey] as SolidColorBrush;
            return brush != null ? brush.Color : Colors.Transparent;
        }
    }
}
